          var color = Module.HEAPU16[srcOffset + x]
          var r = (color >> 10) & 0x1f
          var g = (color >> 5) & 0x1f
          var b = color & 0x1f
          pixels[dstOffset] = (r << 3) | (r >> 2)
          pixels[dstOffset + 1] = (g << 3) | (g >> 2)
          pixels[dstOffset + 2] = (b << 3) | (b >> 2)
          pixels[dstOffset + 3] = 255
          dstOffset = dstOffset + 4
